const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={level:localStorage.amLevel||'Beginner',theme:localStorage.amTheme||'dark',projects:[],active:null,stage:0};
const stages=[['Plan','Decide what you are building'],['Build','Create pages and features'],['Data','Store project information'],['Test','Check that everything works'],['GitHub','Save and upload your project'],['Publish','Put the project online']];
const lessons=[['Project anatomy','Understand how frontend, backend, database and hosting work together.'],['HTML & CSS','Build page structure and control how it looks.'],['JavaScript','Add behaviour and interaction to a website.'],['React & Next.js','Build larger interfaces from reusable components.'],['APIs & backends','Move information safely between the interface and server.'],['Databases','Store users, forms and application information.'],['Git & GitHub','Track versions and share your source code safely.'],['Deployment','Turn local code into a website other people can visit.'],['Security basics','Protect secrets, user data and administrative actions.']];
function api(path,options={}){return fetch('/api/v1'+path,{headers:{'Content-Type':'application/json'},...options}).then(async r=>{if(!r.ok)throw new Error((await r.json().catch(()=>({}))).detail||'Request failed');return r.json()})}
function escapeHtml(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
function showView(name){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===name));$('#pageTitle').textContent={projects:'Projects',guide:'Guided roadmap',learn:'Learning library',settings:'Settings'}[name];$('#projectWorkspace').classList.add('hidden')}
function applyPrefs(){document.body.classList.toggle('light',state.theme==='light');document.body.classList.toggle('reduced',localStorage.amReduced==='1');$('#levelBtn').textContent=state.level+' ▾';$('#levelSelect').value=state.level;$('#motionToggle').checked=localStorage.amReduced==='1';$('#termsToggle').checked=localStorage.amTerms==='1'}
async function loadProjects(){try{const data=await api('/hub/overview');state.projects=data.projects||[]}catch(e){state.projects=JSON.parse(localStorage.amFallbackProjects||'[]')}renderProjects()}
function renderProjects(){const empty=!state.projects.length;$('#emptyState').classList.toggle('hidden',!empty);$('#library').classList.toggle('hidden',empty);$('#projectGrid').innerHTML=state.projects.map(p=>`<article class="project-card" data-id="${p.id}"><div class="project-cover"><span class="stage-tag">${escapeHtml(stages[Math.min(5,Math.floor((p.progress||0)/17))][0])}</span></div><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.description||'Continue building this project.')}</p><small>${p.progress||0}% COMPLETE</small></article>`).join('');$$('.project-card').forEach(c=>c.onclick=()=>openProject(c.dataset.id))}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden')}
function chooseLevel(){modal(`<small>CHOOSE YOUR WORKSPACE</small><h2>How much guidance do you want?</h2><p>This changes the interface complexity, not your project files.</p><div class="choice-grid"><button class="choice" data-level="Beginner"><b>I’m new</b><span>Plain language and one next action.</span></button><button class="choice" data-level="Practising"><b>I’m learning</b><span>Guidance with visible code and technical terms.</span></button><button class="choice" data-level="Professional"><b>I’m experienced</b><span>Compact tools and direct controls.</span></button></div>`);$$('[data-level]').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;localStorage.amLevel=state.level;applyPrefs();closeModal();toast('Workspace changed to '+state.level)})}
function startFlow(type){if(type==='new'||type==='sample')return projectWizard(type==='sample');if(type==='local')return modal(`<small>IMPORT FROM COMPUTER</small><h2>Open an existing project folder</h2><p>Aware Minds will inspect the folder without changing files. The installed desktop version will provide the secure folder picker.</p><div class="form-actions"><button class="ghost" onclick="closeModal()">Cancel</button><button class="primary" onclick="toast('Folder picker belongs to the desktop build')">Choose folder</button></div>`);if(type==='github')return modal(`<small>CONTINUE FROM GITHUB</small><h2>Clone a repository</h2><p>Paste a GitHub repository URL. Authentication is handled by Git Credential Manager, not stored here.</p><div class="form-grid"><label>Repository URL<input placeholder="https://github.com/owner/project"></label></div><div class="form-actions"><button class="ghost" onclick="closeModal()">Cancel</button><button class="primary" onclick="toast('Connect GitHub after creating a project')">Continue</button></div>`);modal(`<small>PROJECT RESCUE</small><h2>What is going wrong?</h2><p>The repair flow will collect the error, identify the affected stage and show every proposed change before applying it.</p><div class="form-grid"><label>Paste the exact error<textarea placeholder="Paste the full error message here"></textarea></label></div><div class="form-actions"><button class="primary" onclick="toast('Diagnostic preview prepared')">Analyze safely</button></div>`)}
function projectWizard(sample=false){modal(`<small>NEW PROJECT · 1 OF 2</small><h2>What do you want to build?</h2><p>Choose the closest option. You can customize it next.</p><div class="choice-grid" id="types"><button class="choice selected" data-type="portfolio"><b>Portfolio</b><span>Show work, skills and contact details.</span></button><button class="choice" data-type="business"><b>Business website</b><span>Services, contact and information pages.</span></button><button class="choice" data-type="blog"><b>Blog</b><span>Publish and organize articles.</span></button><button class="choice" data-type="dashboard"><b>Dashboard</b><span>Manage and visualize information.</span></button><button class="choice" data-type="booking"><b>Booking system</b><span>Accounts, availability and requests.</span></button><button class="choice" data-type="api"><b>Backend API</b><span>Data and operations for another app.</span></button></div><div class="form-actions"><button class="primary" id="wizardNext">Continue →</button></div>`);
let type='portfolio';$$('[data-type]').forEach(b=>b.onclick=()=>{$$('[data-type]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');type=b.dataset.type});$('#wizardNext').onclick=()=>projectDetails(type,sample)}
function projectDetails(type,sample){modal(`<small>NEW PROJECT · 2 OF 2</small><h2>Describe the project simply.</h2><p>We will turn this into pages, features and a technical plan for your approval.</p><form id="projectForm" class="form-grid"><label>Project name<input name="name" required value="${sample?'My First Portfolio':''}" placeholder="Example: My portfolio"></label><label>What should it help people do?<textarea name="description" required placeholder="Example: See my projects and contact me">${sample?'Show my work, skills and contact information.':''}</textarea></label><label><span>Does it need saved information?</span><select name="data"><option value="no">No / I’m not sure</option><option value="yes">Yes, it needs a database</option></select></label><label><span>Will people create accounts?</span><select name="accounts"><option value="no">No</option><option value="yes">Yes</option></select></label><div class="form-actions"><button type="button" class="ghost" onclick="projectWizard()">Back</button><button class="primary">Create my plan →</button></div></form>`);$('#projectForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);createProject({name:f.get('name'),description:f.get('description'),type,data:f.get('data'),accounts:f.get('accounts')})}}
async function createProject(input){const slug=input.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')||'project';const body={name:input.name,slug,description:input.description,status:'planning',priority:'medium',progress:0,website_url:'',repository_url:'',next_action:'Approve the project plan',theme:'purple',local_path:'',database_path:''};let id='local-'+Date.now();try{id=(await api('/hub/projects',{method:'POST',body:JSON.stringify(body)})).id;await loadProjects()}catch(e){const p={...body,id};state.projects.push(p);localStorage.amFallbackProjects=JSON.stringify(state.projects)}closeModal();state.active={...body,id,...input};openProject(id)}
function openProject(id){state.active=state.projects.find(p=>p.id===id)||state.active;if(!state.active)return;state.stage=Math.min(5,Math.floor((state.active.progress||0)/17));$('#projectWorkspace').classList.remove('hidden');renderWorkspace()}
function renderWorkspace(){const p=state.active;$('#projectStage').textContent='STEP '+(state.stage+1)+' OF 6';$('#workspaceTitle').textContent=stages[state.stage][1];$('#nextTitle').textContent=['Review your project plan','Create the first page','Choose what information to save','Run project checks','Connect and save to GitHub','Choose compatible hosting'][state.stage];$('#nextHelp').textContent=['Confirm the goal, pages and features before files are created.','Build visually or open the source code whenever you are ready.','Use a database only when the project actually needs persistent information.','Check layout, links, forms, accessibility and production build.','Review every changed file before saving a version and uploading it.','Aware Minds will recommend a host compatible with your project technology.'][state.stage];$('#workspaceContent').innerHTML=`<div class="plan-board"><div class="plan-summary"><small>PROJECT PLAN</small><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.description||'Define the project goal.')}</p><div class="checklist"><div class="check done"><i></i><span>Project goal described</span></div><div class="check"><i></i><span>Approve pages and navigation</span></div><div class="check"><i></i><span>Choose required features</span></div><div class="check"><i></i><span>Review recommended technology</span></div></div></div></div>`;$('#journey').innerHTML=stages.map((s,i)=>`<div class="journey-step ${i<state.stage?'done':i===state.stage?'current':''}">${i+1}. ${s[0]}</div>`).join('')}
function renderGuides(){$('#guideSteps').innerHTML=stages.map((s,i)=>`<div class="guide-step"><span class="step-number">0${i+1}</span><div><b>${s[0]}</b><span>${s[1]}</span></div></div>`).join('');$('#lessonGrid').innerHTML=lessons.map(x=>`<article class="lesson"><h3>${x[0]}</h3><p>${x[1]}</p><button>Open lesson →</button></article>`).join('')}
function rescue(){modal(`<small>BEGINNER RESCUE</small><h2>You are not stuck.</h2><p id="rescueText">${state.active?'You are working on '+escapeHtml(state.active.name)+'. Your current stage is '+stages[state.stage][0]+'.':'You are in the project library. Start by choosing what you want to do—not a programming language.'}</p><div class="choice-grid"><button class="choice" onclick="closeModal();showView('guide')"><b>Show the full path</b><span>See all six project stages.</span></button><button class="choice" onclick="closeModal();startFlow('sample')"><b>Build a sample</b><span>Learn through a real portfolio.</span></button></div>`)}
function command(open=true){$('#command').classList.toggle('hidden',!open);if(open){$('#commandInput').focus();$('#commandResults').innerHTML=['New project','Open project library','Show guided roadmap','Learn Git and GitHub','Change experience level'].map(x=>`<div class="command-result">${x}</div>`).join('')}}
$$('.nav').forEach(n=>n.onclick=()=>showView(n.dataset.view));$$('[data-start]').forEach(b=>b.onclick=()=>startFlow(b.dataset.start));$('#levelBtn').onclick=chooseLevel;$('#levelSelect').onchange=e=>{state.level=e.target.value;localStorage.amLevel=state.level;applyPrefs()};$('#themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.amTheme=state.theme;applyPrefs()};$('#motionToggle').onchange=e=>{localStorage.amReduced=e.target.checked?'1':'0';applyPrefs()};$('#termsToggle').onchange=e=>localStorage.amTerms=e.target.checked?'1':'0';$('#resetBtn').onclick=()=>{['amLevel','amTheme','amReduced','amTerms'].forEach(k=>localStorage.removeItem(k));location.reload()};$('#lostBtn').onclick=rescue;$('#closeModal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#backLibrary').onclick=()=>{$('#projectWorkspace').classList.add('hidden');showView('projects')};$('#commandBtn').onclick=()=>command();$('#menuBtn').onclick=()=>$('.rail').classList.toggle('open');$('#nextAction').onclick=()=>toast('This step will open the guided builder in the complete desktop release.');$('#explainBtn').onclick=()=>toast($('#nextHelp').textContent);$('#showBtn').onclick=()=>toast('The relevant workspace control is highlighted.');$('#restoreBtn').onclick=()=>toast('No earlier working version exists yet.');$$('.map-node').forEach(n=>n.onclick=()=>$('#mapHelp').textContent=n.textContent.trim()+': '+({front:'the pages and controls people interact with.',back:'the server-side rules that process requests.',data:'structured information saved beyond one visit.',git:'version history and collaboration stored in a repository.',host:'the service that makes your project accessible online.'}[[...n.classList].find(x=>['front','back','data','git','host'].includes(x))]));$('#skipIntro').onclick=()=>$('#intro').classList.add('done');$('#intro').onclick=e=>{if(e.target.id!=='skipIntro')$('#intro').classList.add('done')};setTimeout(()=>$('#intro').classList.add('done'),3300);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command()}if(e.key==='Escape'){command(false);closeModal();$('#intro').classList.add('done')}});applyPrefs();renderGuides();loadProjects();